def name_operands(region,address,operation):
    if (region,address)!=('Action',0x6CEF):return operation
    return operation.replace('#13','@ActionBankCallbackConst.CallbackPage').replace('#A783','@ActionBankedCallbackState.ContextBase').replace('#6D00','@Action.RestoreRuntimePage.Entry')
